// Account-wide auto-discovery; bounded processing; no hand-entered IDs.
// Cycle through *all* completed native WhatsApp one-off campaigns; prioritise active processing.
const rows=$input.all().map(x=>x.json).filter(x=>x&&Object.keys(x).length);
if(rows.some(x=>x.error))return [{json:{hasCampaign:false,availability:'BLOCKED',reason:'CAMPAIGN_INVENTORY_API_UNAVAILABLE'}}];
const active=[],completed=[],seen=new Set(),now=Date.now();
for(const c of rows){
 if(c.campaign_type!=='one_off'||c.inbox?.channel_type!=='Channel::Whatsapp')continue;
 const id=Number(c.id);
 if(!Number.isSafeInteger(id)||id<1||seen.has(id))
    return [{json:{hasCampaign:false,availability:'BLOCKED',reason:'INVALID_OR_DUPLICATE_PROVIDER_ID'}}];
 seen.add(id);
 const entry={campaignId:id,title:String(c.title||'').slice(0,70),campaignStatus:c.campaign_status,
  completedAt:c.completed_at??null,startedAt:c.started_at??null};
 if(c.campaign_status==='processing')active.push(entry);
 else if(c.campaign_status==='completed')completed.push(entry);
}
const newest=a=>a.sort((x,y)=>(Number(y.completedAt||y.startedAt)||0)-(Number(x.completedAt||x.startedAt)||0)||y.campaignId-x.campaignId);
newest(active);newest(completed);
const batchSize=5,activeQuota=2,completedQuota=3,slot=Math.floor(now/(6*3600000));
const rotate=(all,count)=>all.length<=count?all:all.slice((slot%Math.ceil(all.length/count))*count,(slot%Math.ceil(all.length/count)+1)*count);
const work=[...rotate(active,activeQuota),...rotate(completed,completedQuota)];
if(!work.length)return [{json:{hasCampaign:false,availability:'NO_DATA',reason:'NO_NATIVE_WHATSAPP_ONE_OFF_TO_RECONCILE'}}];
return work.map(c=>({json:{...c,hasCampaign:true,readOnly:true,
 scan:{totalActive:active.length,totalCompleted:completed.length,selected:work.length,
   partialScan:active.length+completed.length>work.length,rotationSlot:slot}}}));

// Validate v4.19.0 metrics contract and correct delivered INCLUDING read.
const selected=$('Select Recent Campaigns - Rotating Batches').all().map(x=>x.json).filter(x=>x.hasCampaign);
const items=$input.all(),seen=new Set(),out=[];
for(const item of items){
 const p=Array.isArray(item.pairedItem)?item.pairedItem[0]:item.pairedItem;
 if(!p||!Number.isSafeInteger(p.item)||p.item<0||p.item>=selected.length)
  throw new Error('PROVIDER_METRICS_PAIRING_MISSING');
 const i=p.item;
 if(seen.has(i))throw new Error('PROVIDER_METRICS_PAIRING_DUPLICATE');
 seen.add(i);const c=selected[i],m=item.json||{};
 if(m.error){
  out.push({json:{...c,metricsAvailable:false,blockedReason:'ANALYTICS_ACCESS_OR_PROVIDER_FAILURE',
    providerHttpCode:m.httpCode||null,counts:null},pairedItem:{item:i}});continue;
 }
 const keys=['audience','sent','delivered','read','failed','skipped'];
 if(keys.some(k=>!Number.isSafeInteger(m[k])||m[k]<0))
  throw new Error('INVALID_CHATWOOT_METRICS');
 const s=m.status_counts;
 // When detailed status counts are available, enforce the actual Chatwoot 4.19 contract:
 // delivered = count(status=delivered) + count(status=read).  Never add Read again.
 if(s && typeof s==='object'){
  for(const k of ['queued','skipped','sent','delivered','read','failed'])
   if(!Number.isSafeInteger(s[k])||s[k]<0)throw new Error('INVALID_STATUS_COUNTS');
  if(m.delivered!==s.delivered+s.read||m.read!==s.read||m.failed!==s.failed||m.skipped!==s.skipped)
   throw new Error('CHATWOOT_DELIVERED_READ_COUNT_MISMATCH');
  if(Object.values(s).reduce((a,b)=>a+b,0)!==m.audience)
   throw new Error('CAMPAIGN_AUDIENCE_STATUS_MISMATCH');
 }
 if(m.read>m.delivered||m.delivered>m.audience||m.sent>m.audience||m.failed>m.audience)
  throw new Error('CAMPAIGN_METRIC_COUNT_CONTRADICTION');
 out.push({json:{...c,metricsAvailable:true,
  counts:{audience:m.audience,providerMessageIdsAssigned:m.sent,
   deliveredIncludingRead:m.delivered,readConfirmed:m.read,
   deliveredWithoutRead:m.delivered-m.read,failed:m.failed,skipped:m.skipped,
   queued:s?.queued??null,sentButNotDelivered:s?.sent??null},
  expectedFailed:m.failed},pairedItem:{item:i}});
}
if(seen.size!==selected.length)throw new Error('INCOMPLETE_PROVIDER_METRICS');
return out;

// Final aggregation uses no recipient phone/name/message content and no fabricated CRM mapping.
const meta=$('Attach Campaign Context to Metrics').all().map(x=>x.json),rows=$input.all();
const failures=new Map(),blocked=new Set();
for(const item of rows){
 const raw=item.json||{};
 if(Object.keys(raw).length===0&&!item.pairedItem)continue;
 const p=Array.isArray(item.pairedItem)?item.pairedItem[0]:item.pairedItem;
 if(!p||!Number.isSafeInteger(p.item)||p.item<0||p.item>=meta.length)
  throw new Error('RECIPIENT_PAGE_ATTRIBUTION_MISSING');
 const idx=p.item;
 if(!failures.has(idx))failures.set(idx,[]);
 if(raw.error){blocked.add(idx);continue;}
 if(Object.keys(raw).length===0)continue;
 if(raw.status!=='failed')throw new Error('UNEXPECTED_RECIPIENT_STATUS_IN_FAILURE_QUERY');
 const cid=Number(raw.contact?.id);
 if(!Number.isSafeInteger(cid)||cid<=0)throw new Error('INVALID_CHATWOOT_CONTACT_ID');
 const code=raw.error_code==null?'UNSPECIFIED':String(raw.error_code);
 failures.get(idx).push({cid,code,title:raw.error_title?String(raw.error_title).slice(0,80):null});
}
const reports=[];
for(let i=0;i<meta.length;i++){
 const c=meta[i],items=failures.get(i)||[],seen=new Set(),codes={};
 for(const v of items){
  if(seen.has(v.cid))throw new Error('DUPLICATE_FAILED_CONTACT');
  seen.add(v.cid);
  const key=/^[0-9]{3,8}$/.test(v.code)?v.code:'UNSPECIFIED';
  codes[key]=(codes[key]||0)+1;
 }
 const checks=[];
 if(!c.metricsAvailable)checks.push('ANALYTICS_UNAVAILABLE');
 if(blocked.has(i))checks.push('FAILED_RECIPIENT_API_UNAVAILABLE');
 if(items.length>500||c.expectedFailed>500)checks.push('FAILURE_SCAN_LIMIT_EXCEEDED');
 if(c.metricsAvailable && items.length!==c.expectedFailed)checks.push('FAILURE_COUNT_MISMATCH');
 const status=checks.length?'BLOCKED':'AGGREGATE_VERIFIED';
 reports.push({chatwootCampaignDisplayId:c.campaignId,campaignStatus:c.campaignStatus,
  status,reasons:checks,counts:c.counts,
  errorCodeCounts:status==='AGGREGATE_VERIFIED'?codes:null,
  readIsSubsetOfDelivery:true,
  espoCrmMappingStatus:'UNVERIFIED',messageLevelProviderEvidenceAvailable:false,
  canWriteEspoEvents:false});
}
return [{json:{checkedAt:new Date().toISOString(),mode:'READ_ONLY',
 status:reports.some(x=>x.status==='BLOCKED')?'PARTIAL_OR_BLOCKED':'AGGREGATES_ONLY',
 reports,scan:meta[0]?.scan||null,discoveredCampaigns:meta.length,
 noDoubleCountRule:'deliveredIncludingRead already includes readConfirmed; never sum them',
 campaignAndMessageMappingVerified:false,espocrmWrites:0,sendAttempted:false,
 note:'This uses entitled Chatwoot campaign analytics. Source provides no per-message Meta ID/event time or verified AGE attempt linkage; CRM write is deliberately disabled.'}}];
